function EscapeRegex(value: string): string
{
  return value.replace(/[.+^${}()|[\]\\]/g, "\\$&");
}

function GlobSegmentToRegex(segment: string): string
{
  let regex = "";
  let index = 0;

  while (index < segment.length)
  {
    if (segment[index] === "*")
    {
      if (segment[index + 1] === "*")
      {
        regex += ".*";
        index += 2;
        continue;
      }

      regex += "[^/]*";
      index += 1;
      continue;
    }

    if (segment[index] === "?")
    {
      regex += "[^/]";
      index += 1;
      continue;
    }

    regex += EscapeRegex(segment[index]);
    index += 1;
  }

  return regex;
}

export function GlobToRegExp(pattern: string): RegExp
{
  const normalized = pattern.replace(/\\/g, "/");
  const segments = normalized.split("/");
  const regexParts: string[] = [];

  for (let index = 0; index < segments.length; index++)
  {
    const segment = segments[index];

    if (segment === "**")
    {
      if (index === segments.length - 1)
      {
        regexParts.push("(?:.*)");
      }
      else
      {
        regexParts.push("(?:.*/)?");
      }
      continue;
    }

    regexParts.push(GlobSegmentToRegex(segment));
  }

  return new RegExp(`^${regexParts.join("/")}$`);
}

export function MatchesGlob(relativePath: string, pattern: string): boolean
{
  const normalized = relativePath.replace(/\\/g, "/");
  return GlobToRegExp(pattern).test(normalized);
}

export function MatchesAnyGlob(relativePath: string, patterns: string[]): boolean
{
  for (const pattern of patterns)
  {
    if (MatchesGlob(relativePath, pattern))
    {
      return true;
    }
  }

  return false;
}

import { constants } from "node:fs";
import { access, readdir, stat } from "node:fs/promises";

import { Type } from "typebox";

import { RelativizeDisplayPath } from "../results.js";
import type { ScopedToolContext, ScopedToolDefinition } from "../types.js";
import {
  HandlePathEscape,
  ResolveScopedPath,
  ToolError,
  ToolSuccess,
} from "../toolHelpers.js";

const x_listSchema = Type.Object({
  path: Type.Optional(Type.String({ description: "Directory to list (default: session root)" })),
  limit: Type.Optional(Type.Number({ description: "Maximum number of entries to return (default: 500)" })),
});

const x_defaultLimit = 500;

export function CreateListTool(context: ScopedToolContext): ScopedToolDefinition
{
  return {
    name: "list",
    label: "list",
    description:
      "List directory entries under the session root with file type, size, and modified time.",
    parameters: x_listSchema,
    async execute(_toolCallId, params, signal)
    {
      if (signal?.aborted)
      {
        return ToolError("Operation aborted");
      }

      const pathArg = typeof params.path === "string" ? params.path : ".";
      const limit = typeof params.limit === "number" ? params.limit : x_defaultLimit;

      let absolutePath: string;

      try
      {
        absolutePath = await ResolveScopedPath(context.policy, pathArg);
      }
      catch (error)
      {
        const escapeResult = HandlePathEscape(context, "list", error);

        if (escapeResult)
        {
          return escapeResult;
        }

        throw error;
      }

      const displayPath = RelativizeDisplayPath(context.policy, absolutePath);

      try
      {
        await access(absolutePath, constants.R_OK);
      }
      catch
      {
        return ToolError(`Path not found: ${displayPath}`);
      }

      const directoryStat = await stat(absolutePath);

      if (!directoryStat.isDirectory())
      {
        return ToolError(`Not a directory: ${displayPath}`);
      }

      const entries = await readdir(absolutePath, { withFileTypes: true });
      entries.sort((left, right) => left.name.localeCompare(right.name));

      const lines: string[] = [];
      let count = 0;

      for (const entry of entries)
      {
        if (count >= limit)
        {
          break;
        }

        const entryAbsolute = `${absolutePath}/${entry.name}`;
        context.policy.AssertWithinRoot(entryAbsolute);
        const entryRelative = RelativizeDisplayPath(context.policy, entryAbsolute);
        const entryStat = await stat(entryAbsolute);
        const entryType = entryStat.isDirectory() ? "dir" : entryStat.isSymbolicLink() ? "symlink" : "file";
        const modifiedAt = entryStat.mtime.toISOString();
        lines.push(`${entryRelative}\t${entryType}\t${entryStat.size}\t${modifiedAt}`);
        count += 1;
      }

      let output = `${displayPath}\n${lines.join("\n")}`;

      if (entries.length > limit)
      {
        output += `\n\n[Truncated: showing ${limit} of ${entries.length} entries.]`;
      }

      return ToolSuccess(output, {
        path: displayPath,
        entryCount: count,
        truncated: entries.length > limit,
      });
    },
  };
}

import { constants } from "node:fs";
import { access, readFile, readdir, stat } from "node:fs/promises";
import path from "node:path";

import { Type } from "typebox";

import { MatchesAnyGlob } from "../glob.js";
import { RelativizeDisplayPath } from "../results.js";
import type { ScopedToolContext, ScopedToolDefinition } from "../types.js";
import {
  HandlePathEscape,
  ResolveScopedPath,
  ToolError,
  ToolSuccess,
  x_treeDefaultIgnores,
} from "../toolHelpers.js";

const x_searchTextSchema = Type.Object({
  pattern: Type.String({ description: "Search pattern (regex or literal string)" }),
  path: Type.Optional(Type.String({ description: "Directory or file to search (default: session root)" })),
  include: Type.Optional(Type.Array(Type.String(), { description: "Include globs" })),
  exclude: Type.Optional(Type.Array(Type.String(), { description: "Exclude globs" })),
  ignoreCase: Type.Optional(Type.Boolean({ description: "Case-insensitive search (default: false)" })),
  literal: Type.Optional(Type.Boolean({ description: "Treat pattern as literal string (default: false)" })),
  context: Type.Optional(Type.Number({ description: "Context lines before and after each match (default: 0)" })),
  limit: Type.Optional(Type.Number({ description: "Maximum number of matches (default: 100)" })),
});

const x_defaultLimit = 100;
const x_maxLineLength = 2000;

interface SearchTextOptions
{
  pattern: string;
  include?: string[];
  exclude?: string[];
  ignoreCase: boolean;
  literal: boolean;
  context: number;
  limit: number;
}

interface SearchMatch
{
  file: string;
  lineNumber: number;
  line: string;
}

function IsBinaryBuffer(buffer: Buffer): boolean
{
  const sample = buffer.subarray(0, Math.min(buffer.length, 8192));

  for (const byte of sample)
  {
    if (byte === 0)
    {
      return true;
    }
  }

  return false;
}

function BuildSearchRegex(options: SearchTextOptions): RegExp
{
  const source = options.literal ? options.pattern.replace(/[.*+?^${}()|[\]\\]/g, "\\$&") : options.pattern;
  const flags = options.ignoreCase ? "gi" : "g";
  return new RegExp(source, flags);
}

function ShouldSkipDirectory(name: string): boolean
{
  return x_treeDefaultIgnores.includes(name);
}

function MatchesSearchFilters(relativePath: string, options: SearchTextOptions): boolean
{
  if (options.include && options.include.length > 0)
  {
    if (!MatchesAnyGlob(relativePath, options.include))
    {
      return false;
    }
  }

  if (options.exclude && options.exclude.length > 0)
  {
    if (MatchesAnyGlob(relativePath, options.exclude))
    {
      return false;
    }
  }

  return true;
}

function SearchFileContent(
  displayPath: string,
  content: string,
  regex: RegExp,
  options: SearchTextOptions,
  matches: SearchMatch[],
): void
{
  const lines = content.split("\n");

  for (let lineIndex = 0; lineIndex < lines.length; lineIndex++)
  {
    if (matches.length >= options.limit)
    {
      return;
    }

    const line = lines[lineIndex];
    regex.lastIndex = 0;

    if (!regex.test(line))
    {
      continue;
    }

    const contextBefore = Math.max(0, lineIndex - options.context);
    const contextAfter = Math.min(lines.length - 1, lineIndex + options.context);

    for (let contextIndex = contextBefore; contextIndex <= contextAfter; contextIndex++)
    {
      if (matches.length >= options.limit)
      {
        return;
      }

      let contextLine = lines[contextIndex];

      if (contextLine.length > x_maxLineLength)
      {
        contextLine = `${contextLine.slice(0, x_maxLineLength)}...`;
      }

      matches.push({
        file: displayPath,
        lineNumber: contextIndex + 1,
        line: contextLine,
      });
    }
  }
}

async function WalkSearch(
  policy: ScopedToolContext["policy"],
  absolutePath: string,
  options: SearchTextOptions,
  regex: RegExp,
  matches: SearchMatch[],
): Promise<void>
{
  if (matches.length >= options.limit)
  {
    return;
  }

  const entryStat = await stat(absolutePath);

  if (entryStat.isFile())
  {
    const displayPath = RelativizeDisplayPath(policy, absolutePath);

    if (!MatchesSearchFilters(displayPath, options))
    {
      return;
    }

    const buffer = await readFile(absolutePath);

    if (IsBinaryBuffer(buffer))
    {
      return;
    }

    SearchFileContent(displayPath, buffer.toString("utf-8"), regex, options, matches);
    return;
  }

  if (!entryStat.isDirectory())
  {
    return;
  }

  const entries = await readdir(absolutePath, { withFileTypes: true });
  entries.sort((left, right) => left.name.localeCompare(right.name));

  for (const entry of entries)
  {
    if (matches.length >= options.limit)
    {
      return;
    }

    const entryAbsolute = path.join(absolutePath, entry.name);
    policy.AssertWithinRoot(entryAbsolute);

    if (entry.isDirectory())
    {
      if (!ShouldSkipDirectory(entry.name))
      {
        await WalkSearch(policy, entryAbsolute, options, regex, matches);
      }
      continue;
    }

    await WalkSearch(policy, entryAbsolute, options, regex, matches);
  }
}

export function CreateSearchTextTool(context: ScopedToolContext): ScopedToolDefinition
{
  return {
    name: "search_text",
    label: "search_text",
    description:
      "Search UTF-8 text files under the session root with literal or regex mode, case sensitivity, include/exclude globs, context lines, binary skipping, and match limits.",
    parameters: x_searchTextSchema,
    async execute(_toolCallId, params, signal)
    {
      if (signal?.aborted)
      {
        return ToolError("Operation aborted");
      }

      const pathArg = typeof params.path === "string" ? params.path : ".";
      const options: SearchTextOptions = {
        pattern: String(params.pattern ?? ""),
        include: Array.isArray(params.include) ? params.include.map(String) : undefined,
        exclude: Array.isArray(params.exclude) ? params.exclude.map(String) : undefined,
        ignoreCase: params.ignoreCase === true,
        literal: params.literal === true,
        context: typeof params.context === "number" ? Math.max(0, params.context) : 0,
        limit: typeof params.limit === "number" ? params.limit : x_defaultLimit,
      };

      if (options.pattern.length === 0)
      {
        return ToolError("pattern must not be empty");
      }

      let regex: RegExp;

      try
      {
        regex = BuildSearchRegex(options);
      }
      catch (error)
      {
        return ToolError(
          `Invalid search pattern: ${error instanceof Error ? error.message : String(error)}`,
        );
      }

      let absolutePath: string;

      try
      {
        absolutePath = await ResolveScopedPath(context.policy, pathArg);
      }
      catch (error)
      {
        const escapeResult = HandlePathEscape(context, "search_text", error);

        if (escapeResult)
        {
          return escapeResult;
        }

        throw error;
      }

      const displayPath = RelativizeDisplayPath(context.policy, absolutePath);

      try
      {
        await access(absolutePath, constants.R_OK);
      }
      catch
      {
        return ToolError(`Path not found: ${displayPath}`);
      }

      const matches: SearchMatch[] = [];
      await WalkSearch(context.policy, absolutePath, options, regex, matches);

      const output = matches
        .map((match) => `${match.file}:${match.lineNumber}:${match.line}`)
        .join("\n");

      let text = output || "(no matches)";

      if (matches.length >= options.limit)
      {
        text += `\n\n[Truncated: reached limit=${options.limit}.]`;
      }

      return ToolSuccess(text, {
        path: displayPath,
        matchCount: matches.length,
        truncated: matches.length >= options.limit,
      });
    },
  };
}

import { constants } from "node:fs";
import { access, readdir, stat } from "node:fs/promises";
import path from "node:path";

import { Type } from "typebox";

import { MatchesAnyGlob, MatchesGlob } from "../glob.js";
import { RelativizeDisplayPath } from "../results.js";
import type { ScopedToolContext, ScopedToolDefinition } from "../types.js";
import {
  HandlePathEscape,
  ResolveScopedPath,
  ToolError,
  ToolSuccess,
  x_treeDefaultIgnores,
} from "../toolHelpers.js";

const x_findFilesSchema = Type.Object({
  glob: Type.Optional(Type.String({ description: "Glob pattern to match files, e.g. '*.ts' or '**/*.json'" })),
  extension: Type.Optional(Type.String({ description: "File extension without dot, e.g. 'ts'" })),
  pathSegment: Type.Optional(Type.String({ description: "Require this path segment in the relative path" })),
  include: Type.Optional(Type.Array(Type.String(), { description: "Include globs" })),
  exclude: Type.Optional(Type.Array(Type.String(), { description: "Exclude globs" })),
  path: Type.Optional(Type.String({ description: "Directory to search (default: session root)" })),
  maxDepth: Type.Optional(Type.Number({ description: "Maximum search depth (default: unlimited)" })),
  limit: Type.Optional(Type.Number({ description: "Maximum number of results (default: 1000)" })),
});

const x_defaultLimit = 1000;

interface FindFilesOptions
{
  glob?: string;
  extension?: string;
  pathSegment?: string;
  include?: string[];
  exclude?: string[];
  maxDepth?: number;
  limit: number;
}

function ShouldSkipDirectory(name: string): boolean
{
  return x_treeDefaultIgnores.includes(name);
}

function MatchesFindFilters(relativePath: string, options: FindFilesOptions): boolean
{
  if (options.include && options.include.length > 0)
  {
    if (!MatchesAnyGlob(relativePath, options.include))
    {
      return false;
    }
  }

  if (options.exclude && options.exclude.length > 0)
  {
    if (MatchesAnyGlob(relativePath, options.exclude))
    {
      return false;
    }
  }

  if (options.glob && !MatchesGlob(relativePath, options.glob))
  {
    return false;
  }

  if (options.extension)
  {
    const expected = options.extension.startsWith(".") ? options.extension : `.${options.extension}`;

    if (!relativePath.endsWith(expected))
    {
      return false;
    }
  }

  if (options.pathSegment)
  {
    const segments = relativePath.split("/");

    if (!segments.includes(options.pathSegment))
    {
      return false;
    }
  }

  return true;
}

async function WalkFind(
  policy: ScopedToolContext["policy"],
  absoluteDirectory: string,
  depth: number,
  options: FindFilesOptions,
  results: string[],
): Promise<void>
{
  if (results.length >= options.limit)
  {
    return;
  }

  if (options.maxDepth !== undefined && depth > options.maxDepth)
  {
    return;
  }

  const entries = await readdir(absoluteDirectory, { withFileTypes: true });
  entries.sort((left, right) => left.name.localeCompare(right.name));

  for (const entry of entries)
  {
    if (results.length >= options.limit)
    {
      return;
    }

    const entryAbsolute = path.join(absoluteDirectory, entry.name);
    policy.AssertWithinRoot(entryAbsolute);
    const entryRelative = RelativizeDisplayPath(policy, entryAbsolute);
    const entryStat = await stat(entryAbsolute);

    if (entryStat.isFile() && MatchesFindFilters(entryRelative, options))
    {
      results.push(entryRelative);
    }

    if (entryStat.isDirectory() && !ShouldSkipDirectory(entry.name))
    {
      await WalkFind(policy, entryAbsolute, depth + 1, options, results);
    }
  }
}

export function CreateFindFilesTool(context: ScopedToolContext): ScopedToolDefinition
{
  return {
    name: "find_files",
    label: "find_files",
    description:
      "Discover files under the session root by glob, extension, path segment, include/exclude globs, max depth, and limit.",
    parameters: x_findFilesSchema,
    async execute(_toolCallId, params, signal)
    {
      if (signal?.aborted)
      {
        return ToolError("Operation aborted");
      }

      const pathArg = typeof params.path === "string" ? params.path : ".";
      const options: FindFilesOptions = {
        glob: typeof params.glob === "string" ? params.glob : undefined,
        extension: typeof params.extension === "string" ? params.extension : undefined,
        pathSegment: typeof params.pathSegment === "string" ? params.pathSegment : undefined,
        include: Array.isArray(params.include) ? params.include.map(String) : undefined,
        exclude: Array.isArray(params.exclude) ? params.exclude.map(String) : undefined,
        maxDepth: typeof params.maxDepth === "number" ? params.maxDepth : undefined,
        limit: typeof params.limit === "number" ? params.limit : x_defaultLimit,
      };

      let absolutePath: string;

      try
      {
        absolutePath = await ResolveScopedPath(context.policy, pathArg);
      }
      catch (error)
      {
        const escapeResult = HandlePathEscape(context, "find_files", error);

        if (escapeResult)
        {
          return escapeResult;
        }

        throw error;
      }

      const displayPath = RelativizeDisplayPath(context.policy, absolutePath);

      try
      {
        await access(absolutePath, constants.R_OK);
      }
      catch
      {
        return ToolError(`Path not found: ${displayPath}`);
      }

      const directoryStat = await stat(absolutePath);

      if (!directoryStat.isDirectory())
      {
        return ToolError(`Not a directory: ${displayPath}`);
      }

      const results: string[] = [];
      await WalkFind(context.policy, absolutePath, 0, options, results);

      let output = results.join("\n");

      if (results.length >= options.limit)
      {
        output += `\n\n[Truncated: reached limit=${options.limit}.]`;
      }

      return ToolSuccess(output || "(no matches)", {
        path: displayPath,
        matchCount: results.length,
        truncated: results.length >= options.limit,
      });
    },
  };
}

import assert from "node:assert/strict";
import { readFile } from "node:fs/promises";
import path from "node:path";
import test from "node:test";

import { AssertNoParentLeak } from "../../src/extensions/sheaf-chat/results.js";
import { x_scopedToolNames } from "../../src/extensions/sheaf-chat/tools/createScopedTools.js";
import {
  CreateOutsideSymlink,
  CreateScopedTestFixture,
  RunTool,
  WriteRootFile,
} from "./helpers.js";

function AssertNoAbsoluteLeak(fixture: Awaited<ReturnType<typeof CreateScopedTestFixture>>, text: string): void
{
  assert.doesNotThrow(() => AssertNoParentLeak(text, fixture.context.policy));
  assert.equal(text.includes(fixture.context.policy.canonicalRoot), false);
  assert.equal(text.includes(fixture.outsideDirectory), false);
}

test("CreateScopedTools registers only the scoped tool set", async () =>
{
  const fixture = await CreateScopedTestFixture();
  try
  {
    assert.deepEqual([...fixture.tools.keys()].sort(), [...x_scopedToolNames].sort());
    assert.equal(fixture.tools.has("bash"), false);
    assert.equal(fixture.tools.has("grep"), false);
  }
  finally
  {
    await fixture.cleanup();
  }
});

test("read returns numbered excerpts and rejects escapes", async () =>
{
  const fixture = await CreateScopedTestFixture(async (rootDirectory, outsideDirectory) =>
  {
    await WriteRootFile(rootDirectory, "src/app.ts", "line1\nline2\nline3\n");
    await WriteRootFile(outsideDirectory, "secret.txt", "secret\n");
    await CreateOutsideSymlink(rootDirectory, outsideDirectory, "link.txt", "secret.txt");
  });

  try
  {
    const result = await RunTool(fixture, "read", { path: "src/app.ts", offset: 2, limit: 1 });
    const text = result.content[0]?.text ?? "";
    AssertNoAbsoluteLeak(fixture, text);
    assert.match(text, /^src\/app\.ts/);
    assert.match(text, /2\|line2/);

    const escape = await RunTool(fixture, "read", { path: "../outside/secret.txt" });
    assert.equal(escape.isError, true);
    assert.equal(fixture.activityEvents.length, 1);
